const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('ooc-demo')||'{}')}catch{saved={}}
const state={favorites:[],chats:{},created:[],credits:300,nickname:'Guest Creator',note:'',avatar:'Traveler',mode:'Basic',...saved};
let page='story',genre='Main',query='',sort='Popular',searchType='all',hero=0,selected=null,step=0,draft={type:'story',name:'',description:'',intro:'',prompt:'',tags:'Fantasy',image:''},busy=false;
const titles=['The Academy of Hidden Magic','A Promise Under the Moon','The Last Dragon Knight','Your Rival, Your Roommate','Welcome to the Midnight Café','The Villain’s Second Chance','A Summer We Never Forgot','The City Beyond the Stars','The Prince and the Secret','My Unexpected Companion','The Witch of the Silver Forest','After the World Ends'];
const descriptions=['Your ordinary life ends with one mysterious invitation. What will you become?','A chance encounter. A forgotten promise. A story only you can finish.','The kingdom needs a hero. The dragon has other plans.','There is only one room left—and someone is already waiting.','Where every visitor has a secret, and every conversation changes a life.','You know how this story ends. This time, change the ending.','One last summer together, and a thousand things left unsaid.','Choose your allies and explore a world beyond imagination.'];
const genres=['Main','Rankings','Fantasy','Romance','School Life','Simulation','Adventure','Slice of Life'];
const original=titles.map((name,i)=>({id:'title-'+i,name,description:descriptions[i%8],genre:genres[2+i%6],image:'assets/portrait-'+i+'.svg',creator:['Mellow','Storyweaver','Luna','Aster'][i%4],plays:((i+3)*12.7).toFixed(1)+'K',intro:['The letter on your desk bears a seal you have never seen. As you break it open, a voice calls your name from beyond the door.\n\n“You’re finally here. We’ve been waiting for you.”','Rain falls over the empty street. Beneath the glow of a streetlamp, a familiar face turns toward you.\n\n“I thought you wouldn’t come.”','A distant bell rings through the valley. The stranger lowers their sword and studies you carefully.\n\n“If you’re coming with me, you should know there’s no turning back.”'][i%3]}));
function items(){return [...state.created,...original]}
function persist(){localStorage.setItem('ooc-demo',JSON.stringify(state));historyList()}
function toast(s){$('#toast').textContent=s;$('#toast').style.transform='translateX(-50%) translateY(0)';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.transform='',2400)}
function nav(p){page=p;query='';genre='Main';location.hash=p;render();window.scrollTo(0,0)}
function historyList(){$('#historyList').innerHTML=Object.keys(state.chats).reverse().map(id=>{const t=items().find(t=>t.id===id);return t?`<button class="historyitem" data-chat="${esc(id)}"><img src="${esc(t.image)}" alt=""><span>${esc(t.name)}</span></button>`:''}).join('');$('#profileBtn').innerHTML=`◉ <span>${esc(state.nickname)}</span><span>⚙</span>`}
function card(t,i,rank=false){return `<button class="card ${page==='character'?'character':''}" data-title="${esc(t.id)}"><div class="cover"><img src="${esc(t.image)}" alt="${esc(t.name)}" loading="lazy"><span class="badge">${page==='character'?'Character':'Story'}</span>${rank?`<span class="rank">${i+1}</span>`:''}</div><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><div class="meta">@${esc(t.creator||state.nickname)} &nbsp; ♡ ${t.plays||'New'}</div></button>`}
function section(name,ts,rank=false){return `<section class="section"><div class="sectionhead"><h2>${esc(name)}</h2><button data-all="${esc(name)}">View All ›</button></div><div class="cards">${ts.map((t,i)=>card(t,i,rank)).join('')}</div></section>`}
function footer(){return `<footer class="footer"><div><strong>✱ OOC</strong><p>The Playable Anime</p><p>Interface recreation · local demo</p></div><div><b>Explore</b><button data-page="story">Story</button><button data-page="character">Character</button><button data-page="titles">My Titles</button></div><div><b>Support</b><button data-action="help">Contact & Support</button><button data-action="about">About this demo</button></div></footer>`}
function home(){let ts=items().filter(t=>genre==='Main'||genre==='Rankings'||t.genre===genre);if(sort==='Latest First')ts.reverse();const h=original[hero];return `<div class="notice"><b>Notifications</b><span>OOC: The Playable Anime — your story starts here.</span><button data-action="dismiss" aria-label="Dismiss notification">×</button></div><section class="hero"><div class="herocopy"><h1>${esc(h.name)}</h1><p>${esc(h.description)}</p><button class="explore" data-title="${h.id}">Explore</button></div><div class="herocards"><button class="round" data-hero="-1" aria-label="Previous banner">‹</button><div class="hero-stack"><img src="${original[(hero+11)%12].image}" alt=""><img src="${original[(hero+1)%12].image}" alt=""><img src="${h.image}" alt="${esc(h.name)}"></div><button class="round" data-hero="1" aria-label="Next banner">›</button></div></section><div class="tabs">${genres.map(g=>`<button class="chip ${g===genre?'selected':''}" data-genre="${g}">${g}</button>`).join('')}</div><div class="content">${genre==='Rankings'?`<div class="sectionhead"><h2>Top 100</h2><select id="rankingPeriod" style="width:130px"><option>Daily</option><option>Weekly</option><option>Monthly</option></select></div>${section('Popularity Rankings',ts,true)}`:genre!=='Main'?section(genre,ts):section(page==='character'?'Meet your next favorite character':'Overwhelming Fun! OOC Original',ts.slice(0,5))+section('Trending Now',ts.slice(4,10),true)+section(page==='character'?'New Characters':'New Stories',ts.slice(6,12))}</div>${footer()}`}
function head(title,extra=''){return `<div class="pagehead"><h1>${esc(title)}</h1>${extra}</div>`}
function empty(title,description,action='Explore',p='story'){return `<div class="empty"><div style="font-size:46px">✱</div><b>${esc(title)}</b><p>${esc(description)}</p><button class="secondary" data-page="${p}">${action}</button></div>`}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='story'||page==='character')app.innerHTML=home();else if(page==='detail')app.innerHTML=detail();else if(page==='chat')app.innerHTML=chat();else if(page==='search')app.innerHTML=head('Search')+`<div class="content"><div class="searchbox">⌕ <input id="search" aria-label="Search titles" placeholder="Search stories, characters, creators..." value="${esc(query)}"><button data-action="clearSearch">×</button></div><div class="sectionhead"><div class="steps"><button class="chip selected" data-searchtype="all">All</button><button class="chip" data-searchtype="story">Story</button><button class="chip" data-searchtype="character">Character</button></div><select id="sort" style="width:160px"><option>Popular</option><option ${sort==='Latest First'?'selected':''}>Latest First</option></select></div><div id="searchResults"></div></div>`;else if(page==='titles')app.innerHTML=head('My Titles',`<button class="primary" data-action="create">＋ Create</button>`)+`<div class="content"><div class="steps"><button class="chip selected" data-action="createdTab">Created</button><button class="chip" data-action="favoritesTab">Liked</button></div><div id="mygrid" style="margin-top:28px">${state.created.length?`<div class="cards">${state.created.map((t,i)=>card(t,i)).join('')}</div>`:empty('Create your own world','Bring your stories and characters to life.','Explore')}</div></div>`;else if(page==='history')app.innerHTML=head('History')+`<div class="content">${Object.keys(state.chats).length?`<div class="cards">${items().filter(t=>state.chats[t.id]).map((t,i)=>card(t,i)).join('')}</div>`:empty('Your story is waiting','Start a conversation to see it here.')}</div>`;else if(page==='notifications')app.innerHTML=head('Your notifications')+empty('No notifications',"You don’t have any notifications yet.");else if(page==='credits')app.innerHTML=credits();else if(page==='profile')app.innerHTML=profile();else if(page==='builder')app.innerHTML=builder();if(page==='search'){searchType='all';searchResults();}historyList();if(page==='chat')scrollChat()}
function searchResults(){let ts=items().filter(t=>(searchType==='all'||(t.type||'story')===searchType)&&(t.name+' '+t.description+' '+t.genre+' '+t.creator).toLowerCase().includes(query.toLowerCase()));if(sort==='Latest First')ts.reverse();$('#searchResults').innerHTML=ts.length?`<div class="cards">${ts.map((t,i)=>card(t,i)).join('')}</div>`:empty('No results found','Try another keyword.','Explore');}
function detail(){const t=selected;return head(page==='character'?'Character Information':'Story Information',`<button data-page="story">✕</button>`)+`<div class="detail"><div class="detailtop"><img src="${esc(t.image)}" alt="${esc(t.name)}"><div><small style="color:#999">${t.genre} · ${esc(t.creator||state.nickname)}</small><h1>${esc(t.name)}</h1><p>${esc(t.description)}</p><div class="tags"><span class="chip">#${esc(t.genre)}</span><span class="chip">#Roleplay</span><span class="chip">#Original</span></div><div class="meta">◷ ${t.plays||'0'} conversations &nbsp; ♡ ${state.favorites.includes(t.id)?'Liked':'Popular'}</div><div class="detailactions"><button class="primary" data-chat="${esc(t.id)}">${state.chats[t.id]?'Continue':'Start'} ${selected.type==='character'?'Chat':'Story'} →</button><button class="secondary" data-like="${t.id}">${state.favorites.includes(t.id)?'♥ Liked':'♡ Like'}</button><button class="secondary" data-action="share">↗ Share</button></div></div></div><div class="detailtext"><h2>Introduction</h2><p style="white-space:pre-wrap">${esc(t.intro)}</p><h2>About this title</h2><p>Step into an interactive world where every choice belongs to you. Talk, explore, and shape what happens next.</p><h2>Comments</h2><p>No comments yet. Be the first to leave one.</p><textarea id="comment" placeholder="Write a comment..."></textarea><button class="secondary" style="margin-top:12px" data-action="comment">Post comment</button><div id="comments"></div></div></div>`}
function startChat(id){selected=items().find(t=>t.id===id);if(!selected)return;if(!state.chats[id])state.chats[id]=[{role:'assistant',text:selected.intro||`“Hello, ${state.avatar}. I was hoping we would meet.”`}];page='chat';location.hash='chat/'+id;persist();render()}
function chat(){let ms=state.chats[selected.id]||[];return `<div class="chat"><div class="chathead"><button data-action="backDetail">‹</button><b>${esc(selected.name)}</b><button class="chip" data-action="mode">${esc(state.mode)} ⌄</button><button data-action="chatSettings" aria-label="Session settings">⚙</button><button data-action="chatMenu" aria-label="Chat menu">⋯</button></div><div class="messages" id="messages"><div class="chatintro"><img src="${esc(selected.image)}" alt=""><h2>${esc(selected.name)}</h2><p>Your choices write the story.</p></div>${ms.map((m,i)=>`<div class="msg ${m.role}"><small>${m.role==='user'?esc(state.avatar):esc(selected.name)}</small><div class="bubble">${esc(m.text)}</div><button data-edit="${i}">Edit</button><button data-delete="${i}">Delete</button>${m.role==='assistant'?`<button data-regenerate="${i}">↻ Regenerate</button>`:''}</div>`).join('')}${busy?'<div class="msg"><small>Writing…</small></div>':''}</div><div class="composer"><div class="suggestions"><button data-suggestion="Tell me more about this place.">Tell me more about this place.</button><button data-suggestion="I take a step closer.">I take a step closer.</button><button data-suggestion="What happens next?">What happens next?</button></div><form id="sendForm" class="inputrow"><textarea id="message" placeholder="What do you say or do?" aria-label="Message"></textarea><button type="submit" ${busy?'disabled':''}>↑</button></form><div class="demohint">Demo replies · messages are saved in this browser</div></div></div>`}
function scrollChat(){const m=$('#messages');if(m)m.scrollTop=m.scrollHeight}
function reply(text){const variants=[`They pause, considering your words, then meet your gaze.\n\n“${/place|where/i.test(text)?'This place has more secrets than you might imagine. Let me show you.':/hello|hi/i.test(text)?'It’s good to see you. I was beginning to wonder when you would arrive.':'I knew you would say that. But are you ready for what comes next?'}”\n\nA soft sound comes from behind the door. The next choice is yours.`,`A small smile crosses their face. The room grows quiet around you.\n\n“Then we’ll find out together.”\n\nThey reach toward the door and wait for you to follow. Somewhere beyond it, a new chapter is beginning.`,`They turn back toward you, their expression softening.\n\n“You don’t have to decide everything right now. Tell me what you’re thinking.”\n\nThe world seems to hold its breath, waiting for your answer.`];return variants[state.chats[selected.id].length%3]}
function send(text){text=text.trim();if(!text||busy)return;state.chats[selected.id].push({role:'user',text});busy=true;persist();render();setTimeout(()=>{state.chats[selected.id].push({role:'assistant',text:reply(text)});busy=false;persist();if(page==='chat')render()},650)}
function openModal(html){modal.innerHTML=`<button class="close" data-action="closeModal" aria-label="Close">×</button>${html}`;modal.showModal()}
function credits(){return head('Credits')+`<div class="content"><div class="balance">Your Credits<b>ϟ ${state.credits.toLocaleString()}</b><button class="secondary" data-action="checkin">Daily Check-in ＋100</button><button class="secondary" data-action="creditHistory">Credit History</button></div><h2>Refill Credits Now!</h2><p style="color:#888">Choose your next adventure.</p><div class="plans">${[[1000,'$4.99'],[5500,'$24.99'],[12000,'$49.99']].map(([n,p])=>`<div class="plan"><span style="color:var(--brand)">ϟ Credits</span><h2>${n.toLocaleString()}</h2><p>${p}</p><button class="primary" data-refill="${n}">Refill Now</button></div>`).join('')}</div><p class="demohint" style="margin-top:24px">Demo wallet. No payment is collected.</p></div>`}
function profile(){return head('My Account')+`<div class="content" style="max-width:900px"><h2>◉ ${esc(state.nickname)}</h2><div class="settingrow"><div>Nickname<small>Your creator profile</small></div><input id="nickname" value="${esc(state.nickname)}"></div><div class="settingrow"><div>Appearance<small>Personalize your interface</small></div><select id="theme"><option value="dark">Dark</option><option value="light" ${state.theme==='light'?'selected':''}>Light</option></select></div><div class="settingrow"><div>Language</div><select id="language"><option>English</option><option>简体中文</option><option>日本語</option><option>한국어</option></select></div><div class="settingrow"><div>Avatars<small>How characters recognize you</small></div><input id="avatar" value="${esc(state.avatar)}"></div><label>User Note</label><textarea id="userNote" placeholder="Preferences and details characters should remember">${esc(state.note)}</textarea><div style="margin-top:20px"><button class="primary" data-action="saveProfile">Save Changes</button><button class="secondary" data-action="login">Sign in</button></div><div class="settingrow"><span>Titles you like</span><button class="secondary" data-action="showLiked">View favorites →</button></div><div class="settingrow"><span>Help Center</span><button class="secondary" data-action="help">Open Guide →</button></div></div>`}
const steps=['Character Setup','Intro','Prompt','Advanced Features','Character Details'];
function builder(){const body=step===0?`<label>Type</label><select id="draftType"><option value="story">Story</option><option value="character" ${draft.type==='character'?'selected':''}>Character</option></select><label>Title image</label><label class="upload" for="upload">${draft.image?`<img src="${draft.image}" alt="Preview">`:'＋ Upload image'}</label><input id="upload" type="file" accept="image/*" hidden><label>Name *</label><input id="draftName" maxlength="80" placeholder="Give your world a name" value="${esc(draft.name)}"><label>One-line Introduction</label><textarea id="draftDescription" placeholder="What makes your title special?">${esc(draft.description)}</textarea>`:step===1?`<label>Opening Greeting</label><textarea id="draftIntro" style="height:260px" placeholder="Set the scene and invite the user into your world...">${esc(draft.intro)}</textarea>`:step===2?`<label>Character Prompt</label><textarea id="draftPrompt" maxlength="3000" style="height:260px" placeholder="Personality, tone, appearance, relationships, and world setting...">${esc(draft.prompt)}</textarea><p class="demohint">Up to 3,000 characters</p>`:step===3?`<label>Suggested Replies</label><textarea placeholder="Example actions or dialogue...">Say hello\nExplore the world\nAsk a question</textarea><label>Keyword Book</label><textarea placeholder="Add background and world-building details..."></textarea><button class="secondary" data-action="advancedPreview" style="margin-top:16px">Preview settings</button>`:`<label>Genre</label><select id="draftGenre">${genres.slice(2).map(g=>`<option ${draft.tags===g?'selected':''}>${g}</option>`).join('')}</select><label>Visibility</label><select><option>Private</option><option>Public (demo)</option></select><h2>${esc(draft.name||'Untitled')}</h2><p style="color:#999">${esc(draft.description||'Your new story is ready.')}</p><p class="demohint">Publishing saves your title locally in this demo.</p>`;return head('Create a '+(draft.type==='character'?'Character':'Story'),'<button data-page="titles">✕</button>')+`<div class="builder"><div class="steps">${steps.map((s,i)=>`<button class="step ${i===step?'current':''}" data-step="${i}">${i+1}. ${s}</button>`).join('')}</div><h2 style="margin-top:32px">${steps[step]}</h2>${body}<div class="builderfooter"><button class="secondary" data-action="builderPrev">${step?'Back':'Cancel'}</button><button class="primary" data-action="builderNext">${step===4?'Publish Title':'Next Step →'}</button></div></div>`}
function captureDraft(){if($('#draftName')){draft.name=$('#draftName').value;draft.description=$('#draftDescription').value;draft.type=$('#draftType').value}if($('#draftIntro'))draft.intro=$('#draftIntro').value;if($('#draftPrompt'))draft.prompt=$('#draftPrompt').value;if($('#draftGenre'))draft.tags=$('#draftGenre').value}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;searchResults()}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;searchResults()}if(e.target.id==='rankingPeriod'){toast(e.target.value+' rankings');$('.cards').innerHTML=original.slice().reverse().map((t,i)=>card(t,i,true)).join('')}if(e.target.id==='theme'){state.theme=e.target.value;document.body.classList.toggle('light',state.theme==='light');persist()}if(e.target.id==='language')toast('Language setting saved (demo content remains English)');if(e.target.id==='upload'&&e.target.files[0]){if(e.target.files[0].size>4e6)return toast('Choose an image smaller than 4 MB');const r=new FileReader();r.onload=()=>{draft.image=r.result;captureDraft();render()};r.readAsDataURL(e.target.files[0])}});
document.addEventListener('submit',e=>{if(e.target.id==='sendForm'){e.preventDefault();send($('#message').value)}});
document.addEventListener('keydown',e=>{if(e.target.id==='message'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(e.target.value)}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.page){if(modal.open)modal.close();nav(d.page);return}if(b.id==='collapse'){document.body.classList.toggle('collapsed');return}if(d.title){selected=items().find(t=>t.id===d.title);page='detail';location.hash='title/'+d.title;render();window.scrollTo(0,0);return}if(d.chat){startChat(d.chat);return}if(d.genre){genre=d.genre;render();return}if(d.hero){hero=(hero+Number(d.hero)+12)%12;render();return}if(d.all){genre=d.all==='Trending Now'?'Rankings':genre;app.innerHTML=head(d.all)+`<div class="content"><div class="cards">${items().map((t,i)=>card(t,i)).join('')}</div></div>`;window.scrollTo(0,0);return}if(d.like){const i=state.favorites.indexOf(d.like);i<0?state.favorites.push(d.like):state.favorites.splice(i,1);persist();render();return}if(d.suggestion){$('#message').value=d.suggestion;$('#message').focus();return}if(d.searchtype){searchType=d.searchtype;document.querySelectorAll('[data-searchtype]').forEach(x=>x.classList.toggle('selected',x===b));toast(d.searchtype==='all'?'Showing all titles':'Showing '+d.searchtype+' titles');searchResults();return}if(d.refill){openModal(`<h2>Refill Credits</h2><p>This is a demo checkout. No charge will be made.</p><p>ϟ ${Number(d.refill).toLocaleString()} credits</p><div class="modalactions"><button class="secondary" data-action="closeModal">Cancel</button><button class="primary" data-addcredits="${d.refill}">Add demo credits</button></div>`);return}if(d.addcredits){state.credits+=Number(d.addcredits);persist();modal.close();render();toast('Demo credits added');return}if(d.step){captureDraft();step=Number(d.step);render();return}if(d.edit!==undefined){const i=Number(d.edit);openModal(`<h2>Edit message</h2><textarea id="editText">${esc(state.chats[selected.id][i].text)}</textarea><div class="modalactions"><button class="primary" data-saveedit="${i}">Save</button></div>`);return}if(d.saveedit!==undefined){state.chats[selected.id][Number(d.saveedit)].text=$('#editText').value;persist();modal.close();render();return}if(d.delete!==undefined){state.chats[selected.id].splice(Number(d.delete),1);persist();render();return}if(d.regenerate!==undefined){state.chats[selected.id][Number(d.regenerate)].text=reply('continue');persist();render();return}
switch(d.action){case'closeModal':modal.close();break;case'dismiss':$('.notice').remove();break;case'clearSearch':query='';$('#search').value='';searchResults();break;case'backDetail':page='detail';render();break;case'share':try{await navigator.clipboard.writeText(location.href);toast('Link copied')}catch{toast('Copy this page’s address to share')}break;case'comment':{const t=$('#comment').value.trim();if(t){const p=document.createElement('p');p.textContent=state.nickname+': '+t;$('#comments').appendChild(p);$('#comment').value='';toast('Comment added in this session')}break}case'create':step=0;page='builder';render();break;case'builderPrev':captureDraft();if(step){step--;render()}else nav('titles');break;case'builderNext':captureDraft();if(!draft.name.trim()){step=0;render();toast('Please enter a name');return}if(step<4){step++;render()}else{const t={id:'created-'+Date.now(),name:draft.name,description:draft.description,intro:draft.intro||'“Welcome. Your story begins now.”',prompt:draft.prompt,type:draft.type,genre:draft.tags,image:draft.image||original[0].image,creator:state.nickname,plays:'New'};state.created.unshift(t);persist();draft={type:'story',name:'',description:'',intro:'',prompt:'',tags:'Fantasy',image:''};nav('titles');toast('Title published in your browser')}break;case'advancedPreview':toast('Advanced settings are placeholders in this demo');break;case'favoritesTab':case'showLiked':if(page!=='titles'){page='titles';render()}$('#mygrid').innerHTML=state.favorites.length?`<div class="cards">${items().filter(t=>state.favorites.includes(t.id)).map((t,i)=>card(t,i)).join('')}</div>`:empty('Your favorites list is empty','Like a title to collect your preferred titles here');break;case'createdTab':render();break;case'checkin':{const today=new Date().toLocaleDateString();if(state.checked===today)toast('Already checked in today');else{state.checked=today;state.credits+=100;persist();render();toast('You earned 100 credits!')}break}case'creditHistory':openModal(`<h2>Credit History</h2><p>Demo balance: ϟ ${state.credits}</p><p style="color:#999">Demo credits have no monetary value.</p>`);break;case'saveProfile':state.nickname=$('#nickname').value||'Guest Creator';state.avatar=$('#avatar').value||'Traveler';state.note=$('#userNote').value;persist();toast('Changes saved');break;case'login':openModal('<h2>Welcome to OOC</h2><p>Continue into your next story.</p><button class="secondary" style="width:100%;margin:12px 0" data-action="demoLogin">Continue with Google (demo)</button><button class="primary" style="width:100%" data-action="demoLogin">Continue as Guest</button><p class="demohint">No real account or credentials are required.</p>');break;case'demoLogin':modal.close();toast('Welcome, '+state.nickname);break;case'mode':openModal(`<h2>Conversation Mode</h2>${['Basic','Skillful','Extensive','Superb','Premium'].map(m=>`<button class="settingrow" style="width:100%" data-mode="${m}"><span>${m}</span><span>${m===state.mode?'✓':'Select'}</span></button>`).join('')}<p class="demohint">Mode selection is a UI demo.</p>`);break;case'chatSettings':openModal(`<h2>Session Settings</h2><label>Avatar name</label><input id="sessionAvatar" value="${esc(state.avatar)}"><label>User Note</label><textarea id="sessionNote">${esc(state.note)}</textarea><label>Output Length</label><input type="range" min="200" max="2000" value="800"><button class="secondary" style="margin-top:16px" data-action="memories">Memories</button><div class="modalactions"><button class="primary" data-action="saveSession">Save</button></div>`);break;case'saveSession':state.avatar=$('#sessionAvatar').value;state.note=$('#sessionNote').value;persist();modal.close();render();break;case'memories':openModal('<h2>Memories</h2><div class="steps"><span class="chip selected">Long-term</span><span class="chip">Temporary</span><span class="chip">Relationships</span><span class="chip">Goals</span></div><label>Long-term memory</label><textarea id="memory" placeholder="Add important events or facts...">'+esc(state.memory||'')+'</textarea><div class="modalactions"><button class="primary" data-action="saveMemory">Save</button></div>');break;case'saveMemory':state.memory=$('#memory').value;persist();modal.close();toast('Memory saved');break;case'chatMenu':openModal('<h2>Conversation</h2><button class="settingrow" style="width:100%" data-action="exportChat">Export conversation ↓</button><button class="settingrow" style="width:100%" data-action="restartChat">Start a new conversation ↻</button>');break;case'restartChat':state.chats[selected.id]=[{role:'assistant',text:selected.intro}];persist();modal.close();render();toast('New conversation started');break;case'exportChat':{const data=state.chats[selected.id].map(m=>(m.role==='user'?state.avatar:selected.name)+': '+m.text).join('\n\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'text/plain'}));a.download='conversation.txt';a.click();URL.revokeObjectURL(a.href);modal.close();break}case'help':openModal('<h2>OOC Guide</h2><p>Explore a title, choose Start Story, then type what you say or do.</p><p>Use Session Settings to edit your avatar, notes, and memories. Use Create to build a new story or character.</p><p>This recreation uses local demo replies and placeholder artwork.</p>');break;case'about':openModal('<h2>About this recreation</h2><p>A standalone interface recreation based on publicly available OOC styles and feature documentation.</p><p>Artwork, story content, authentication, payments, and AI replies are placeholders. This demo is not affiliated with OOC.</p>');break;}if(d.mode){state.mode=d.mode;persist();modal.close();render()}});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(h.startsWith('title/')){selected=items().find(t=>t.id===h.slice(6));if(selected){page='detail';render()}}else if(h.startsWith('chat/')){if(page!=='chat')startChat(h.slice(5))}else if(['story','character','titles','credits','history','profile','search','notifications'].includes(h)&&h!==page){page=h;render()}});
document.body.classList.toggle('light',state.theme==='light');render();if(location.hash){const h=location.hash.slice(1);if(h.startsWith('title/')){selected=items().find(t=>t.id===h.slice(6));if(selected){page='detail';render()}}else if(h.startsWith('chat/'))startChat(h.slice(5));else if(['story','character','titles','credits','history','profile','search','notifications'].includes(h)){page=h;render()}}
